import json
def f(g):
    H,W=len(g),len(g[0])
    o=[row[:] for row in g]
    # flood fill from corners through 0s, but demo shows enclosed zeros -> 2? Check: input (0,3) stays 0, but enclosed interior becomes 2. Actually rule: cells enclosed by the marker color become 2? The marker here is 3; zeros adjacent to edge of grid stay 0. Find which region contains... demo: (0,3)=0 top edge row - open. (1,3) was 0 now 2 — inside closed loop of 3s. Flood from grid border over 0s with 4-connectivity; unreached 0s -> 2.
    vis=[[False]*W for _ in range(H)]
    from collections import deque
    q=deque()
    for i in range(H):
        for j in (0,W-1):
            if g[i][j]==0 and not vis[i][j]: vis[i][j]=True;q.append((i,j))
    for j in range(W):
        for i in (0,H-1):
            if g[i][j]==0 and not vis[i][j]: vis[i][j]=True;q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<H and 0<=nj<W and g[ni][nj]==0 and not vis[ni][nj]:
                vis[ni][nj]=True;q.append((ni,nj))
    for i in range(H):
        for j in range(W):
            if g[i][j]==0 and not vis[i][j]: o[i][j]=2
    return o
