def hull(points):
    points = sorted(set(points))
    if len(points) <= 2: return points
    lower=[]
    for p_ in points:
        while len(lower) >= 2 and cross(lower[-2],lower[-1],p_) <= 0:
            lower.pop()
        lower.append(p_)
    upper=[]
    for p_ in reversed(points):
        while len(upper) >= 2 and cross(upper[-2],upper[-1],p_) <= 0:
            upper.pop()
        upper.append(p_)
    return lower[:-1] + upper[:-1]
